/**
 * Unit tests for TokenBuffer.writeTree(TreeNode node).
 */
public class TokenBuffer_writeTree_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteTree_WithObjectNode() throws IOException {
        // Arrange
        ObjectNode root = mapper.createObjectNode();
        root.put("key", "value");
        root.put("number", 123);

        // Act
        tokenBuffer.writeTree(root);

        // Assert
        // We verify by serializing the buffer to a generator and checking the output
        // Or by checking the parser output of the buffer
        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("key", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getText());
        assertEquals("number", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(123, parser.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }










}

