    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }









    @Test
    public void testWriteTree_WithComplexTree() throws IOException {
        // Arrange
        ObjectNode root = mapper.createObjectNode();
        ArrayNode array = mapper.createArrayNode();
        array.add(mapper.createObjectNode().put("inner", "val"));
        root.set("list", array);

        // Act
        tokenBuffer.writeTree(root);

        // Assert
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("list", parser.getCurrentName());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("inner", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("val", parser.getText());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }


}

